1	package com.example.starter.water;
2	
3	import org.springframework.dao.EmptyResultDataAccessException;
4	import org.springframework.jdbc.core.JdbcTemplate;
5	import org.springframework.jdbc.core.RowMapper;
6	import org.springframework.jdbc.support.GeneratedKeyHolder;
7	import org.springframework.jdbc.support.KeyHolder;
8	import org.springframework.stereotype.Repository;
9	
10	import java.math.BigDecimal;
11	import java.sql.PreparedStatement;
12	import java.sql.Statement;
13	import java.util.List;
14	import java.util.Objects;
15	
16	/**
17	 * 灌区配水数据访问层（JdbcTemplate，参数化 SQL）。
18	 * 时间一律为 UTC 纳秒时间戳；水量为 DECIMAL(19,3)。
19	 */
20	@Repository
21	public class WaterRepository {
22	
23	    /** 供水窗口行。 */
24	    public record WindowRow(long id, String windowKey, String channelId, long startNanos, long endNanos,
25	                            BigDecimal plannedVolume, long createdNanos) {
26	    }
27	
28	    /** 配水申请行；amount 为不可改写的原申请水量，heldAmount 为当前持有额度。 */
29	    public record AllocationRow(long id, String allocationKey, long windowId, String userId, BigDecimal amount,
30	                                BigDecimal heldAmount, String requester, String status,
31	                                long createdNanos, long updatedNanos) {
32	    }
33	
34	    /** 转让流水行，创建后不可变。 */
35	    public record TransferRow(long id, String transferKey, long windowId, String sourceAllocationKey,
36	                              String targetAllocationKey, BigDecimal amount, String actor, long createdNanos) {
37	    }
38	
39	    /** 限供行。 */
40	    public record CurtailmentRow(long id, long windowId, BigDecimal volume, String status, long createdNanos,
41	                                 Long cancelledNanos) {
42	    }
43	
44	    /** 幂等命令行；response 为 null 表示响应尚未写回（同事务内）。 */
45	    public record CommandRow(String commandKey, String operation, String params, String response,
46	                             long createdNanos) {
47	    }
48	
49	    private static final RowMapper<WindowRow> WINDOW_MAPPER = (rs, n) -> new WindowRow(
50	            rs.getLong("id"), rs.getString("window_key"), rs.getString("channel_id"),
51	            rs.getLong("start_nanos"), rs.getLong("end_nanos"),
52	            rs.getBigDecimal("planned_volume"), rs.getLong("created_nanos"));
53	
54	    private static final RowMapper<AllocationRow> ALLOCATION_MAPPER = (rs, n) -> new AllocationRow(
55	            rs.getLong("id"), rs.getString("allocation_key"), rs.getLong("window_id"),
56	            rs.getString("user_id"), rs.getBigDecimal("amount"), rs.getBigDecimal("held_amount"),
57	            rs.getString("requester"), rs.getString("status"),
58	            rs.getLong("created_nanos"), rs.getLong("updated_nanos"));
59	
60	    private static final String ALLOCATION_SELECT =
61	            "SELECT id, allocation_key, window_id, user_id, amount, held_amount, requester, status,"
62	                    + " created_nanos, updated_nanos";
63	
64	    private static final RowMapper<TransferRow> TRANSFER_MAPPER = (rs, n) -> new TransferRow(
65	            rs.getLong("id"), rs.getString("transfer_key"), rs.getLong("window_id"),
66	            rs.getString("source_allocation_key"), rs.getString("target_allocation_key"),
67	            rs.getBigDecimal("amount"), rs.getString("actor"), rs.getLong("created_nanos"));
68	
69	    private static final RowMapper<CurtailmentRow> CURTAILMENT_MAPPER = (rs, n) -> new CurtailmentRow(
70	            rs.getLong("id"), rs.getLong("window_id"), rs.getBigDecimal("volume"), rs.getString("status"),
71	            rs.getLong("created_nanos"),
72	            rs.getObject("cancelled_nanos") == null ? null : rs.getLong("cancelled_nanos"));
73	
74	    private static final RowMapper<CommandRow> COMMAND_MAPPER = (rs, n) -> new CommandRow(
75	            rs.getString("command_key"), rs.getString("operation"), rs.getString("params"),
76	            rs.getString("response"), rs.getLong("created_nanos"));
77	
78	    private final JdbcTemplate jdbc;
79	
80	    public WaterRepository(JdbcTemplate jdbc) {
81	        this.jdbc = jdbc;
82	    }
83	
84	    /** 插入窗口并返回自增主键。 */
85	    public long insertWindow(String windowKey, String channelId, long startNanos, long endNanos,
86	                             BigDecimal plannedVolume, long createdNanos) {
87	        KeyHolder keys = new GeneratedKeyHolder();
88	        jdbc.update(con -> {
89	            PreparedStatement ps = con.prepareStatement(
90	                    "INSERT INTO supply_window (window_key, channel_id, start_nanos, end_nanos, planned_volume, created_nanos)"
91	                            + " VALUES (?, ?, ?, ?, ?, ?)", Statement.RETURN_GENERATED_KEYS);
92	            ps.setString(1, windowKey);
93	            ps.setString(2, channelId);
94	            ps.setLong(3, startNanos);
95	            ps.setLong(4, endNanos);
96	            ps.setBigDecimal(5, plannedVolume);
97	            ps.setLong(6, createdNanos);
98	            return ps;
99	        }, keys);
100	        return Objects.requireNonNull(keys.getKey()).longValue();
101	    }
102	
103	    /** 按主键查询窗口，不存在返回 null。 */
104	    public WindowRow findWindowById(long id) {
105	        try {
106	            return jdbc.queryForObject(
107	                    "SELECT id, window_key, channel_id, start_nanos, end_nanos, planned_volume, created_nanos"
108	                            + " FROM supply_window WHERE id = ?", WINDOW_MAPPER, id);
109	        } catch (EmptyResultDataAccessException e) {
110	            return null;
111	        }
112	    }
113	
114	    /** 按主键锁定窗口行（FOR UPDATE），用于串行化批准与限供。 */
115	    public WindowRow lockWindowById(long id) {
116	        try {
117	            return jdbc.queryForObject(
118	                    "SELECT id, window_key, channel_id, start_nanos, end_nanos, planned_volume, created_nanos"
119	                            + " FROM supply_window WHERE id = ? FOR UPDATE", WINDOW_MAPPER, id);
120	        } catch (EmptyResultDataAccessException e) {
121	            return null;
122	        }
123	    }
124	
125	    /** 判断同渠道是否存在与 [startNanos, endNanos) 重叠的窗口（相邻合法）。 */
126	    public boolean existsOverlappingWindow(String channelId, long startNanos, long endNanos) {
127	        Integer count = jdbc.queryForObject(
128	                "SELECT COUNT(*) FROM supply_window WHERE channel_id = ? AND start_nanos < ? AND ? < end_nanos",
129	                Integer.class, channelId, endNanos, startNanos);
130	        return count != null && count > 0;
131	    }
132	
133	    /** 插入申请（初始 REQUESTED）并返回主键。 */
134	    public long insertAllocation(String allocationKey, long windowId, String userId, BigDecimal amount,
135	                                 String requester, long nowNanos) {
136	        KeyHolder keys = new GeneratedKeyHolder();
137	        jdbc.update(con -> {
138	            PreparedStatement ps = con.prepareStatement(
139	                    "INSERT INTO allocation (allocation_key, window_id, user_id, amount, held_amount, requester, status, created_nanos, updated_nanos)"
140	                            + " VALUES (?, ?, ?, ?, 0, ?, 'REQUESTED', ?, ?)", Statement.RETURN_GENERATED_KEYS);
141	            ps.setString(1, allocationKey);
142	            ps.setLong(2, windowId);
143	            ps.setString(3, userId);
144	            ps.setBigDecimal(4, amount);
145	            ps.setString(5, requester);
146	            ps.setLong(6, nowNanos);
147	            ps.setLong(7, nowNanos);
148	            return ps;
149	        }, keys);
150	        return Objects.requireNonNull(keys.getKey()).longValue();
151	    }
152	
153	    /** 按业务键查询申请，不存在返回 null。 */
154	    public AllocationRow findAllocationByKey(String allocationKey) {
155	        try {
156	            return jdbc.queryForObject(ALLOCATION_SELECT + " FROM allocation WHERE allocation_key = ?",
157	                    ALLOCATION_MAPPER, allocationKey);
158	        } catch (EmptyResultDataAccessException e) {
159	            return null;
160	        }
161	    }
162	
163	    /** 按业务键锁定申请行（FOR UPDATE），用于串行化转让的源/目标争用，不存在返回 null。 */
164	    public AllocationRow lockAllocationByKey(String allocationKey) {
165	        try {
166	            return jdbc.queryForObject(
167	                    ALLOCATION_SELECT + " FROM allocation WHERE allocation_key = ? FOR UPDATE",
168	                    ALLOCATION_MAPPER, allocationKey);
169	        } catch (EmptyResultDataAccessException e) {
170	            return null;
171	        }
172	    }
173	
174	    /**
175	     * 更新申请状态与变更时间，并同步持有额度：批准时持有额度等于原申请水量，取消时归零，
176	     * REQUESTED 保持当前持有额度不变。
177	     */
178	    public void updateAllocationStatus(long id, String status, long updatedNanos) {
179	        jdbc.update("UPDATE allocation SET status = ?, updated_nanos = ?,"
180	                + " held_amount = CASE WHEN ? = 'APPROVED' THEN amount WHEN ? = 'CANCELLED' THEN 0"
181	                + " ELSE held_amount END WHERE id = ?",
182	                status, updatedNanos, status, status, id);
183	    }
184	
185	    /** 转让扣减源持有额度（不得为负由事务内校验保证）并记录变更时间。 */
186	    public void decrementHeldAmount(long id, BigDecimal delta, long updatedNanos) {
187	        jdbc.update("UPDATE allocation SET held_amount = held_amount - ?, updated_nanos = ? WHERE id = ?",
188	                delta, updatedNanos, id);
189	    }
190	
191	    /** 窗口当前所有 APPROVED 申请的当前持有额度之和（BigDecimal 精确求和），无则 0。 */
192	    public BigDecimal sumApprovedAmount(long windowId) {
193	        BigDecimal sum = jdbc.queryForObject(
194	                "SELECT COALESCE(SUM(held_amount), 0) FROM allocation WHERE window_id = ? AND status = 'APPROVED'",
195	                BigDecimal.class, windowId);
196	        return sum == null ? BigDecimal.ZERO : sum;
197	    }
198	
199	    /** 插入限供（ACTIVE）并返回主键。 */
200	    public long insertCurtailment(long windowId, BigDecimal volume, long createdNanos) {
201	        KeyHolder keys = new GeneratedKeyHolder();
202	        jdbc.update(con -> {
203	            PreparedStatement ps = con.prepareStatement(
204	                    "INSERT INTO curtailment (window_id, volume, status, created_nanos, cancelled_nanos)"
205	                            + " VALUES (?, ?, 'ACTIVE', ?, NULL)", Statement.RETURN_GENERATED_KEYS);
206	            ps.setLong(1, windowId);
207	            ps.setBigDecimal(2, volume);
208	            ps.setLong(3, createdNanos);
209	            return ps;
210	        }, keys);
211	        return Objects.requireNonNull(keys.getKey()).longValue();
212	    }
213	
214	    /** 查询窗口当前生效限供，无则 null。 */
215	    public CurtailmentRow findActiveCurtailment(long windowId) {
216	        try {
217	            return jdbc.queryForObject(
218	                    "SELECT id, window_id, volume, status, created_nanos, cancelled_nanos"
219	                            + " FROM curtailment WHERE window_id = ? AND status = 'ACTIVE'", CURTAILMENT_MAPPER, windowId);
220	        } catch (EmptyResultDataAccessException e) {
221	            return null;
222	        }
223	    }
224	
225	    /** 取消限供：置为 CANCELLED 并记录取消时间。 */
226	    public void cancelCurtailment(long id, long cancelledNanos) {
227	        jdbc.update("UPDATE curtailment SET status = 'CANCELLED', cancelled_nanos = ? WHERE id = ?",
228	                cancelledNanos, id);
229	    }
